mapper.select:
SELECT ch.channel_code as channelCode, ch.channel_name as channelName, de.device_code as deviceCode, de.device_name as deviceName, ac.config_id AS configId, ac.preset_id as presetId, ac.preset_name as presetName, ac.algorithm_code AS algorithmCode, ac.algorithm_name AS algorithmName, ac.points, ac.img, ac.task_id AS taskId, ac.status, ac.pos_type AS posType, ac.industry_code AS industryCode, ac.industry_code_his AS industryCodeHis, ac.app_ver_code AS appVerCode, ac.app_ver_code_his AS appVerCodeHis FROM vm_algorithm_config ac LEFT JOIN vm_device_info_t de on de.device_code = ac.device_code LEFT JOIN vm_channel_info_t ch on ch.channel_code = ac.channel_code WHERE ac.tenant_id = #{customerCode} and ac.order_code = #{orderCode}
AND ac.device_code in
#{item}
AND(
(ac.algorithm_code = #{item.algorithmCode} and ac.device_code = #{item.deviceCode})
)
AND ac.delete_flag = #{deleteFlag}
AND ac.status = #{status}
AND ac.industry_code = #{industryCode}
AND ac.industry_code in
#{item}
AND ac.app_ver_code = #{appVerCode}

mapper.update:
update vm_algorithm_config set algorithm_status = #{onstatus}, status =#{status}, modifier = 'system', update_time = now(), delete_flag = 0 where config_id in
#{item}
and delete_flag = 1 and modifier = 'system'

update vm_algorithm_config set algorithm_status = #{onstatus}, status =#{status}, modifier = 'system', update_time = now(), delete_flag = 1 where config_id in
#{item}
and delete_flag = 0

mapper.select:
select distinct a.algorithm_code,a.algorithm_name,b.algorithm_shape from vm_order_algorithms a inner join vm_algorithm_info_t b on b.algorithm_code = a.algorithm_code and b.delete_flag = '0' left join vm_order_devices e on e.order_code = a.order_code and e.tenant_id = a.tenant_id and a.package_code = e.package_code and e.delete_flag = '0' left join vm_order_customer voc on a.order_code = voc.order_code and voc.delete_flag = '0' where a.delete_flag = '0' and voc.ord_status in (0,1,2)
and a.tenant_id =#{tenantId}
and e.device_code =#{deviceCode}
and a.industry_code = #{industryCode}

mapper.update:
update vm_order_algorithms
set ord_status = 3, update_time = now()
where order_code = #{orderCode} and ord_status in (0,1,2);
